void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Нормализируем координаты
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // для правильного соотношения сторон

    // Параметры шестиугольной симметрии
    float sqrt3 = 1.7320508;
    float angle = 3.1415926 / 6.0; // 30 градусов

    // Преобразуем координаты для шестиугольной симметрии
    vec2 p = vec2(
        uv.x * sqrt3 - uv.y,
        uv.x + uv.y * sqrt3
    );

    p = mod(p, 2.0) - 1.0;

    // Применяем симметрию
    p = abs(p);
    p = min(p, 2.0 - p);

    // Простой градиент цвета на основе симметричных координат
    vec3 color = 0.5 + 0.5 * cos(iTime + vec3(0.0, 2.0, 4.0) + length(p) * 6.28318);

    // Выводим цвет на экран
    fragColor = vec4(color, 1.0);
}
